create extension if not exists pgcrypto;
create table if not exists public.creator_profiles(user_id uuid primary key references auth.users(id) on delete cascade,username text unique not null check(length(username) between 3 and 30),display_name text not null default 'Lking Creator',bio text not null default '',avatar_url text,followers_count bigint not null default 0,following_count bigint not null default 0,total_views bigint not null default 0,created_at timestamptz not null default now());
create table if not exists public.creator_posts(id uuid primary key default gen_random_uuid(),creator_id uuid not null references auth.users(id) on delete cascade,media_url text not null,caption text not null default '',views bigint not null default 0,likes bigint not null default 0,comments bigint not null default 0,status text not null default 'published' check(status in ('draft','published','hidden')),created_at timestamptz not null default now());
create table if not exists public.post_likes(user_id uuid not null references auth.users(id) on delete cascade,post_id uuid not null references public.creator_posts(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,post_id));
create table if not exists public.creator_follows(follower_id uuid not null references auth.users(id) on delete cascade,creator_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(follower_id,creator_id),check(follower_id<>creator_id));
create table if not exists public.post_comments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,post_id uuid not null references public.creator_posts(id) on delete cascade,body text not null check(length(body) between 1 and 500),created_at timestamptz not null default now());
create table if not exists public.live_rooms(id uuid primary key default gen_random_uuid(),host_id uuid not null references auth.users(id) on delete cascade,title text not null,category text not null default 'عام',status text not null default 'live' check(status in ('live','ended')),viewer_count integer not null default 0,started_at timestamptz not null default now(),ended_at timestamptz);
create table if not exists public.live_chat(id bigint generated always as identity primary key,room_id uuid not null references public.live_rooms(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,message text not null check(length(message) between 1 and 300),created_at timestamptz not null default now());
create table if not exists public.creator_referrals(code text primary key,owner_id uuid not null references auth.users(id) on delete cascade,signups integer not null default 0,created_at timestamptz not null default now());
create table if not exists public.creator_challenges(id uuid primary key default gen_random_uuid(),title text not null,description text not null,reward integer not null default 0,active boolean not null default true,starts_at timestamptz not null default now(),ends_at timestamptz not null);
alter table public.creator_profiles enable row level security;alter table public.creator_posts enable row level security;alter table public.post_likes enable row level security;alter table public.creator_follows enable row level security;alter table public.post_comments enable row level security;alter table public.live_rooms enable row level security;alter table public.live_chat enable row level security;alter table public.creator_referrals enable row level security;alter table public.creator_challenges enable row level security;
create policy "profiles public read" on public.creator_profiles for select using(true);create policy "profiles own insert" on public.creator_profiles for insert with check(auth.uid()=user_id);create policy "profiles own update" on public.creator_profiles for update using(auth.uid()=user_id);
create policy "posts public read" on public.creator_posts for select using(status='published' or auth.uid()=creator_id);create policy "posts own insert" on public.creator_posts for insert with check(auth.uid()=creator_id);create policy "posts own update" on public.creator_posts for update using(auth.uid()=creator_id);create policy "posts own delete" on public.creator_posts for delete using(auth.uid()=creator_id);
create policy "likes read" on public.post_likes for select using(true);create policy "likes own insert" on public.post_likes for insert with check(auth.uid()=user_id);create policy "likes own delete" on public.post_likes for delete using(auth.uid()=user_id);
create policy "follows read" on public.creator_follows for select using(true);create policy "follows own insert" on public.creator_follows for insert with check(auth.uid()=follower_id);create policy "follows own delete" on public.creator_follows for delete using(auth.uid()=follower_id);
create policy "comments read" on public.post_comments for select using(true);create policy "comments own insert" on public.post_comments for insert with check(auth.uid()=user_id);create policy "comments own delete" on public.post_comments for delete using(auth.uid()=user_id);
create policy "live public read" on public.live_rooms for select using(true);create policy "live own insert" on public.live_rooms for insert with check(auth.uid()=host_id);create policy "live own update" on public.live_rooms for update using(auth.uid()=host_id);
create policy "chat public read" on public.live_chat for select using(true);create policy "chat own insert" on public.live_chat for insert with check(auth.uid()=user_id);
create policy "referrals own read" on public.creator_referrals for select using(auth.uid()=owner_id);create policy "referrals own insert" on public.creator_referrals for insert with check(auth.uid()=owner_id);
create policy "challenges public read" on public.creator_challenges for select using(true);
alter publication supabase_realtime add table public.live_rooms;alter publication supabase_realtime add table public.live_chat;
